// @ts-check
import js from "@eslint/js";
import { defineConfig, globalIgnores } from "eslint/config";
import globals from "globals";
import tseslint from "typescript-eslint";

export { featureBoundaries } from "./feature-boundaries.js";

/**
 * Paths that are never linted: build output, caches and generated code.
 * `packages/api-types` is generated by ts-rs and must not be edited by hand (CLAUDE.md).
 */
export const ignores = [
  "**/node_modules/**",
  "**/dist/**",
  "**/build/**",
  "**/coverage/**",
  "**/.turbo/**",
  "**/.expo/**",
  "**/target/**",
  "**/api-types/**",
];

/**
 * Base ESLint flat config for every TypeScript/JavaScript package in the monorepo.
 *
 * Type-aware rules are enabled through the TypeScript project service, so each
 * package only needs a `tsconfig.json` next to its `eslint.config.js`.
 *
 * @param {{ tsconfigRootDir: string }} options
 *   `tsconfigRootDir` must be the consuming package's directory (`import.meta.dirname`).
 */
export function baseConfig({ tsconfigRootDir }) {
  return defineConfig(
    globalIgnores(ignores),
    js.configs.recommended,
    tseslint.configs.recommendedTypeChecked,
    {
      languageOptions: {
        ecmaVersion: "latest",
        sourceType: "module",
        globals: { ...globals.es2023 },
        parserOptions: {
          projectService: true,
          tsconfigRootDir,
        },
      },
      linterOptions: {
        reportUnusedDisableDirectives: "error",
      },
      rules: {
        eqeqeq: ["error", "always"],
        "no-console": ["warn", { allow: ["warn", "error"] }],
        "@typescript-eslint/consistent-type-imports": "error",
        "@typescript-eslint/no-unused-vars": [
          "error",
          { argsIgnorePattern: "^_", varsIgnorePattern: "^_" },
        ],
      },
    },
    {
      // Plain config/script files run in Node.
      files: ["**/*.{js,mjs,cjs}"],
      languageOptions: { globals: { ...globals.node } },
    },
  );
}

export default baseConfig;
